import { strict as assert } from "node:assert";
import { test } from "node:test";
import { slugify } from "./slugify.mjs";

test("lowercases and joins on hyphens", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("collapses runs of whitespace to a single hyphen", () => {
  assert.equal(slugify("Hello   World"), "hello-world");
});

test("strips characters that are not letters, digits or hyphens", () => {
  assert.equal(slugify("Hello, World!"), "hello-world");
});

test("leading and trailing whitespace is collapsed and trimmed", () => {
  assert.equal(slugify("  Hello,   World!   "), "hello-world");
});

test("handles special characters mixed with words", () => {
  assert.equal(slugify("Foo & Bar (baz)"), "foo-bar-baz");
});

test("digits are preserved", () => {
  assert.equal(slugify("Test 123 abc"), "test-123-abc");
});

test("hyphens in input are preserved", () => {
  assert.equal(slugify("hello--world"), "hello-world");
});

test("returns empty string when all chars stripped", () => {
  assert.equal(slugify("!@#$%"), "");
});
